def search(nums, target):
    l, r = 0, len(nums) - 1      # 闭区间 [l, r]
    while l <= r:
        mid = (l + r) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:   # 目标在右半
            l = mid + 1
        else:
            r = mid - 1
    return -1

