def searchRange(nums, target):
    def find(first):
        l, r, pos = 0, len(nums) - 1, -1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target:
                pos = mid                  # 命中后继续逼近
                if first: r = mid - 1      # 找左界继续向左
                else: l = mid + 1          # 找右界继续向右
            elif nums[mid] < target:
                l = mid + 1
            else:
                r = mid - 1
        return pos
    return [find(True), find(False)]
